const names=['MIN','기사','이미지','영상','파이널'];
const page=document.body.dataset.page||'기사';
const titles={MIN:['Hello, I’m MIN','배우고 기록하며, 나만의 시선을 만들어갑니다.','AI를 활용해 생각을 글과 이미지, 영상으로 표현하는 과정을 담고 있습니다.'],기사:['The Journal','생각을 읽고, 새로운 관점을 쓰다.','AI와 함께 탐구하고 직접 다듬은 기사들을 모았습니다.'],이미지:['Visual Notes','상상에서 시작된, 한 장의 장면.','프롬프트와 시각 실험으로 쌓아가는 이미지 아카이브입니다.'],영상:['Motion Studies','아이디어에 움직임을 더하다.','스토리보드부터 편집까지, AI 영상 제작 과정을 기록합니다.'],파이널:['Final Project','배움의 조각을 하나의 프로젝트로.','기획, 글, 이미지, 영상을 연결한 마지막 작업을 소개합니다.']};
const art=(cls='art')=>`<img class="${cls}" src="assets/still-life.png" alt="크림색 공간의 분홍 유리 아치와 크롬 구체로 구성한 AI 생성 정물 이미지">`;
const articles=[['AI와 함께 쓰되, 나의 시선으로 완성하기','생성형 AI를 글쓰기의 출발점으로 삼고, 질문과 검증으로 나만의 문장을 만드는 과정.','AI는 초안을 빠르게 제시하지만, 어떤 질문을 던지고 무엇을 남길지 결정하는 일은 작성자의 몫이다. 이번 실습에서는 같은 주제에 서로 다른 독자와 목적을 설정해 초안을 비교했다.\n\n첫 단계는 질문을 구체화하는 것이다. 독자가 누구인지, 읽고 나서 무엇을 알게 되어야 하는지 먼저 정리했다. 다음으로 초안 속 사실과 의견을 나누고, 확인되지 않은 정보는 삭제하거나 검증 대상으로 표시했다.\n\n마지막에는 소리 내어 읽으며 불필요한 문장을 덜어냈다. 빠르게 만드는 도구를 사용할수록 천천히 판단하는 시간이 필요하다는 점을 배웠다.'],['좋은 답변은 좋은 질문에서 시작된다','프롬프트를 바꾸며 발견한 세 가지 차이.','역할, 맥락, 결과 형식을 구체화하며 결과를 비교한 실습이다. 같은 질문에도 독자와 목적을 추가하자 글의 깊이와 표현 방식이 달라졌다.\n\n한 번의 답변으로 끝내지 않고 부족한 조건을 보완하며 대화하는 방식이 유용했다. 다음 실습에서는 실제 자료를 바탕으로 출처 확인 과정까지 연결할 예정이다.'],['데이터가 이야기가 되는 순간','숫자를 읽고, 독자에게 필요한 맥락을 더하다.','수치 자체보다 비교 기준과 맥락이 중요하다. 이 실습에서는 가상의 데이터를 정리하고, 제목과 설명을 달아 하나의 이야기로 구성했다.\n\n상관관계를 인과관계로 표현하지 않는지, 축과 단위가 정확한지 점검했다. 시각화는 보기 좋은 그림이 아니라 판단을 돕는 도구라는 점을 기록했다.'],['AI 시대, 창작자의 역할을 묻다','도구의 속도와 사람의 판단 사이에서.','기획부터 결과 선택까지, 사람의 판단이 필요한 순간을 정리했다. 도구는 다양한 선택지를 만들지만 작업의 목적과 기준은 사람이 세워야 한다.\n\n결과물을 고르는 기준을 먼저 기록하면 반복 작업의 방향이 선명해진다. 이 글은 교육 포트폴리오를 위한 임시 예시이며 실제 취재 기사가 아니다.']];
const journal=`<div class="section-label"><span>01 / FEATURED STORY</span><span>글로 남긴 배움의 기록</span></div><section class="feature">${art()}<div class="feature-copy"><span class="tag">EDITOR’S PICK · AI 글쓰기</span><h2>${articles[0][0]}</h2><p>${articles[0][1]}</p><div class="meta">2026.09.10 &nbsp; · &nbsp; 실습 노트 01</div><button class="pill" data-article="0">기사 읽기 <span>↗</span></button></div></section><div class="section-label"><span>MORE STORIES</span><span>03 ARTICLES</span></div><section class="article-grid">${articles.slice(1).map((a,i)=>`<article class="article-card"><span class="number">0${i+2}</span><div class="meta">LEARNING JOURNAL · 예시 콘텐츠</div><h3>${a[0]}</h3><p>${a[1]}</p><button class="text-button" data-article="${i+1}">기사 읽기 ↗</button></article>`).join('')}</section>`;
const gallery=`<div class="section-label"><span>02 / SELECTED VISUALS</span><span>하나의 이미지, 다섯 가지 시각 실험</span></div><section class="gallery">${['Soft Geometry','A Little Warmer','In Monochrome','Pink Perspective','Vintage Light'].map((t,i)=>`<figure><button class="image-button" data-image="${i}" aria-label="${t} 이미지 확대">${art()}</button><figcaption><span>${t}</span><small>0${i+1} / ${i?'색감 변형':'AI 원본'}</small></figcaption></figure>`).join('')}</section><div class="band"><div><span class="eyebrow">BEHIND THE IMAGE</span><h3>같은 프롬프트에서 발견한 다른 분위기</h3><p>빛, 소재, 색감을 탐구하는 정물 이미지 실습.</p></div><button class="pill" id="prompt-button">프롬프트 보기 ↗</button></div>`;
const videos=`<div class="section-label"><span>03 / THE SCREENING ROOM</span><span>STORY → FRAME → MOTION</span></div><section class="cinema"><div class="screen"><div class="screen-title">Small moments,<br>new perspectives.<small>AI MOTION STUDY / 01</small><button class="play" data-video="0" aria-label="영상 제작 노트 보기">▶</button></div></div><div class="cinema-copy"><span class="tag">영상 기획 예시</span><h2>평범한 하루를<br>새롭게 바라보는 법</h2><p>창가에 스며드는 빛, 책장을 넘기는 손, 오후의 작은 쉼. 일상의 세 장면을 연결하는 짧은 영상 기획입니다.</p><div class="meta">30초 기획 · 16:9 · 라이프스타일</div><button class="pill" data-video="0">제작 노트 보기 ↗</button></div></section><section class="video-list">${['빛과 그림자의 대화','상상을 현실로, 브랜드 필름','30초로 전하는 나의 배움'].map((t,i)=>`<article class="video-row"><span class="eyebrow">0${i+2}</span><div><h3>${t}</h3><p>${['무드 필름 · 15초 기획','브랜드 스토리 · 30초 기획','교육 회고 · 30초 기획'][i]}</p></div><button class="text-button" data-video="${i+1}">기획 보기 ↗</button></article>`).join('')}</section><p class="note">현재 영상은 기획 예시입니다. ‘자료 미리보기’에서 실제 영상 파일을 선택하면 재생할 수 있습니다.</p>`;
const final=`<div class="section-label"><span>04 / CAPSTONE PROJECT</span><span>FROM LEARNING TO MAKING</span></div><section class="project-banner"><div><span class="tag">FINAL PROJECT · 기획 예시</span><h2>작은 쉼을 전하는<br>AI 라이프스타일 매거진</h2><p>바쁜 일상 속 잠깐의 여유를 주제로,<br>하나의 이야기를 글과 이미지, 영상으로 확장합니다.</p><div class="project-stats"><div><strong>3가지</strong>콘텐츠 형식</div><div><strong>4단계</strong>제작 과정</div><div><strong>1개의</strong>일관된 이야기</div></div><a class="pill filled" href="#process">프로젝트 살펴보기 ↓</a></div>${art()}</section><div class="section-label" id="process"><span>THE PROCESS</span><span>아이디어에서 결과물까지</span></div><section class="process"><article><b>01.</b><h3>질문하고 기획하기</h3><p>‘짧은 콘텐츠로 쉼을 전할 수 있을까?’에서 출발해 독자와 메시지, 콘텐츠의 방향을 정의합니다.</p></article><article><b>02.</b><h3>만들고 연결하기</h3><p>기사의 중심 문장을 이미지 프롬프트와 영상 스토리보드로 연결해 공통된 톤을 만듭니다.</p></article><article><b>03.</b><h3>검토하고 다듬기</h3><p>정보의 정확성과 표현의 일관성을 살피고 피드백을 반영합니다. 마지막에는 제작 과정을 기록합니다.</p></article></section><div class="band"><div><span class="eyebrow">REFLECTION / 04</span><h3>도구를 배우는 것에서, 나의 관점을 만드는 것으로.</h3><p>완성된 결과물과 회고를 이곳에 차곡차곡 남길 예정입니다.</p></div><a class="pill" href="기사.html">작업 기록 읽기 ↗</a></div>`;
const introduce=`<div class="section-label"><span>00 / ABOUT MIN</span><span>LEARN · CREATE · RECORD</span></div><section class="about-layout"><div class="about-portrait">${art()}<span>MIN’S CREATIVE NOTE</span></div><article class="about-copy"><span class="tag">안녕하세요, MIN입니다.</span><h2>호기심을 질문으로 바꾸고,<br>배운 것을 콘텐츠로 만듭니다.</h2><p>한국경제 AI 교육을 통해 생성형 AI를 익히고 있습니다. 새로운 도구를 단순히 사용하는 데서 멈추지 않고, 나의 관점과 이야기를 더해 의미 있는 결과물로 만드는 과정을 중요하게 생각합니다.</p><p>이 포트폴리오는 수업에서 만든 기사, 이미지, 영상 그리고 파이널 프로젝트를 기록하는 공간입니다. 아직 채워가는 중이지만, 매 작업마다 무엇을 시도했고 무엇을 배웠는지 솔직하게 남기겠습니다.</p><a class="pill filled" href="기사.html">작업 둘러보기 ↗</a></article></section><section class="about-cards"><article><span class="eyebrow">01 / INTEREST</span><h3>관심 분야</h3><p>AI 콘텐츠 기획, 글쓰기, 이미지 생성, 영상 스토리텔링에 관심이 있습니다.</p></article><article><span class="eyebrow">02 / APPROACH</span><h3>작업 방식</h3><p>먼저 질문하고, 여러 가능성을 실험한 뒤, 목적에 맞는 결과를 골라 세심하게 다듬습니다.</p></article><article><span class="eyebrow">03 / GOAL</span><h3>배움의 목표</h3><p>AI의 속도와 사람의 판단을 연결해 나만의 언어와 시선이 담긴 콘텐츠를 만들고 싶습니다.</p></article></section><blockquote class="about-quote">“작은 호기심도 기록하면 다음 작업의 시작점이 된다.”<small>MIN · CREATIVE PORTFOLIO</small></blockquote>`;
const featuredVideo=`<section class="featured-video" aria-labelledby="featured-video-title"><div class="featured-video-label"><span class="eyebrow">FEATURED VIDEO</span><h2 id="featured-video-title">MIN의 영상 미리보기</h2></div><div class="video-embed"><iframe src="https://www.youtube-nocookie.com/embed/tWx9MtcXMSc" title="MIN의 YouTube 영상 미리보기" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div></section>`;
const youtubeSection=`<section class="making-section" aria-labelledby="making-title"><span class="eyebrow">04 / MY CHANNEL</span><h2 id="making-title">제가 만드는 것들</h2><p>좋아하는 이야기와 순간을 영상으로 기록하고 있습니다.</p><a class="youtube-button" href="https://www.youtube.com/@hayanbyeol_hosistar" target="_blank" rel="noopener noreferrer" aria-label="내가 제일 좋아하는 유튜브 채널 새 탭에서 열기">내가 제일 좋아하는 유튜브 채널 <span aria-hidden="true">↗</span></a></section>`;
const introducePage=introduce.replace('<blockquote class="about-quote">',`${youtubeSection}<blockquote class="about-quote">`);
document.querySelector('#app').innerHTML=`<a class="skip" href="#main">본문으로 이동</a><header><a class="brand" href="introduce.html">AI Atelier<span>HANKYUNG · LEARNING ARCHIVE</span></a><nav aria-label="주 메뉴">${names.map(n=>`<a href="${n==='MIN'?'introduce':n}.html" ${n===page?'class="active" aria-current="page"':''}>${n==='파이널'?'파이널 프로젝트':n}</a>`).join('')}</nav><span class="edition">PORTFOLIO / 2026</span></header><main class="wrap" id="main">${page==='MIN'?featuredVideo:''}<section class="intro"><span class="eyebrow">한국경제 AI 교육 · CREATIVE PORTFOLIO</span><div class="title-row"><h1>${titles[page][0].split(' ').map((t,i)=>i?`<i>${t}</i>`:t).join(' ')}</h1><div class="badge">Made<br>with AI<small>CURATED BY ME</small></div></div><div class="intro-bottom"><p><strong>${titles[page][1]}</strong><br>${titles[page][2]}</p>${page==='MIN'?'<a class="pill" href="#about">나를 소개합니다 ↓</a>':'<button class="pill" id="add">+ 자료 미리보기</button>'}</div></section><div id="about">${({MIN:introducePage,기사:journal,이미지:gallery,영상:videos,파이널:final})[page]}</div><section id="local-items" aria-live="polite"></section><p class="note">이 포트폴리오의 글·이미지·프로젝트는 구성을 보여주기 위한 임시 예시입니다.</p><footer><div class="footer-top"><div class="footer-title">Keep learning.<br>Keep creating.</div><div><p>한국경제 AI 교육 포트폴리오</p><p>배운 것을 만들고, 만든 것을 기록합니다.</p><a href="#main">맨 위로 ↑</a></div></div><div class="footer-bottom"><span>© 2026 AI Atelier. Personal learning portfolio.</span><span>개인 교육 포트폴리오 · 공식 한국경제 사이트가 아닙니다.</span></div></footer></main><dialog id="detail"><button class="close" aria-label="닫기">×</button><div id="detail-content"></div></dialog><dialog id="upload"><button class="close" aria-label="닫기">×</button><h2>${page} 자료 미리보기</h2><p>파일을 선택하면 이 페이지 아래에서 확인할 수 있습니다. 서버에 업로드되거나 저장되지 않으며, 새로고침하면 사라집니다.</p><label for="file">${page==='영상'?'영상 파일 (MP4, WebM)':page==='이미지'?'이미지 파일 (PNG, JPG, WebP)': '문서 파일 (TXT, PDF)'}</label><input id="file" type="file" accept="${page==='영상'?'video/mp4,video/webm':page==='이미지'?'image/png,image/jpeg,image/webp':'.txt,.pdf'}"><p class="status" id="upload-status" role="status"></p></dialog>`;
const detail=document.querySelector('#detail'),content=document.querySelector('#detail-content');
function show(html){content.innerHTML=html;detail.showModal()}
document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('[data-article]').forEach(b=>b.addEventListener('click',()=>{const a=articles[Number(b.dataset.article)];show(`<span class="eyebrow">LEARNING JOURNAL · 임시 예시</span><h2>${a[0]}</h2>${a[2].split('\n\n').map(p=>`<p>${p}</p>`).join('')}`)}));
document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{show('<h2>Visual study</h2>');const im=b.querySelector('img').cloneNode();im.style.filter=getComputedStyle(b.querySelector('img')).filter;content.append(im)}));
document.querySelector('#prompt-button')?.addEventListener('click',()=>show('<span class="eyebrow">IMAGE PROMPT</span><h2>Soft Geometry</h2><p>크림색 받침 위에 놓인 크롬 구체와 반투명 분홍 유리 아치. 버터 옐로 배경, 작은 체리 레드 구체, 부드러운 햇살. 잡지 화보 같은 정물 사진. 글자 없이.</p><p>갤러리의 다른 이미지는 같은 원본에 색감 변형을 적용한 예시입니다.</p>'));
document.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>show('<span class="eyebrow">STORYBOARD · 영상 기획 예시</span><h2>'+['평범한 하루를 새롭게 바라보는 법','빛과 그림자의 대화','상상을 현실로, 브랜드 필름','30초로 전하는 나의 배움'][Number(b.dataset.video)]+'</h2><p><strong>시작</strong> — 창가의 빛과 사물의 질감을 가까이 담아 분위기를 설정합니다.</p><p><strong>전개</strong> — 시선이 머무는 세 장면을 부드러운 전환으로 연결합니다.</p><p><strong>마무리</strong> — 여백이 있는 장면 위에 핵심 메시지 한 문장을 남깁니다.</p><p class="note">실제 영상 파일은 아직 등록되지 않았습니다.</p>')));
document.querySelector('#add')?.addEventListener('click',()=>document.querySelector('#upload').showModal());
document.querySelector('#file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const status=document.querySelector('#upload-status');if(f.size>100*1024*1024){status.textContent='100MB 이하의 파일을 선택해 주세요.';return}const isImage=/^image\/(png|jpeg|webp)$/.test(f.type),isVideo=/^video\/(mp4|webm)$/.test(f.type),isText=/\.txt$/i.test(f.name),isPdf=/\.pdf$/i.test(f.name);if(!(page==='이미지'?isImage:page==='영상'?isVideo:isText||isPdf)){status.textContent='지원되는 형식의 파일을 선택해 주세요.';return}try{const el=document.createElement('article');el.className='added';const h=document.createElement('h3');h.textContent=f.name;el.append(h);const label=document.createElement('p');label.textContent='이 브라우저에서만 표시되는 임시 미리보기';el.append(label);if(isImage||isVideo){const media=document.createElement(isVideo?'video':'img');media.src=URL.createObjectURL(f);if(isVideo)media.controls=true;else media.alt=f.name;el.append(media)}else if(isText){const pre=document.createElement('pre');pre.textContent=await f.text();el.append(pre)}else{const link=document.createElement('a');link.href=URL.createObjectURL(f);link.target='_blank';link.rel='noopener';link.textContent='PDF 열기 ↗';link.className='pill';el.append(link)}document.querySelector('#local-items').append(el);document.querySelector('#upload').close();status.textContent='';e.target.value='';el.scrollIntoView({behavior:'smooth',block:'center'})}catch{status.textContent='파일을 읽지 못했습니다. 다시 선택해 주세요.'}});
